window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-b68465f8387403ce"]={"versions": [{"id": "FIG-b68465f8387403ce", "releases": ["R4.0.3", "R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodell-Struktur der eigenständigen Dokumentation (Standalone Documentation Overview) im Rahmen der AUTOSAR Generic Structure Template (AUTOSAR_TPS_GenericStructureTemplate). Das Diagramm spezifiziert die hierarchische und gemischte Strukturierung von Kapiteln, Unterthemen und Dokumentationsblöcken einschließlich Abfrage- und Variationsmechanismen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell definiert folgende Klassen, Stereotypen und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><strong>Chapter</strong> (<em>Identifiable</em>, <em>Paginateable</em>): Repräsentiert ein Dokumentkapitel. Besitzt eine gerichtete Komposition <code>+chapterModel</code> mit Kardinalität 1 zu <strong>ChapterModel</strong>.</li>\n<li><strong>ChapterModel</strong>: Aggregiert über farblich hervorgehobene (blaue) gerichtete Kompositionen drei alternative bzw. kombinierbare Kind-Elemente:</li>\n<li><code>+chapterContent</code> (0..1) zu <strong>ChapterContent</strong></li>\n<li><code>+topic1</code> (0..1) zu <strong>TopicOrMsrQuery</strong></li>\n<li><code>+chapter</code> (0..1) zu <strong>ChapterOrMsrQuery</strong></li>\n<li><strong>ChapterOrMsrQuery</strong> («atpMixed»): Bindet rekursiv über eine gerichtete Komposition <code>+chapter</code> (1) mit dem Stereotyp «atpVariation» wieder an <strong>Chapter</strong> an.</li>\n<li><strong>TopicOrMsrQuery</strong> («atpMixed»): Komponiert über <code>+topic1</code> (1) unter dem Stereotyp «atpVariation» die Klasse <strong>Topic1</strong>.</li>\n<li><strong>Topic1</strong> (<em>Identifiable</em>, <em>Paginateable</em>): Repräsentiert ein Unterthema erster Ordnung.</li>\n<li><strong>ChapterContent</strong> («atpMixed») und <strong>Topic1</strong>: Komponieren beide über gerichtete Kompositionen <code>+topicContent</code> (jeweils 0..1) die Klasse <strong>TopicContentOrMsrQuery</strong>.</li>\n<li><strong>TopicContentOrMsrQuery</strong> («atpMixed»): Komponiert über <code>+topicContent</code> (1) die Klasse <strong>TopicContent</strong>.</li>\n<li><strong>TopicContent</strong> («atpMixed»): Komponiert auf Blockebene:</li>\n<li><code>+table</code> (0..1) zu <strong>Table</strong> (<em>Paginateable</em>) mit dem Stereotyp «atpVariation»</li>\n<li><code>+blockLevelContent</code> (ohne explizite Kardinalitätsangabe) zu <strong>DocumentationBlock</strong> («atpMixed»)</li>\n<li><strong>Table</strong> (<em>Paginateable</em>): Repräsentiert Tabellenstrukturen im Dokument.</li>\n<li><strong>DocumentationBlock</strong> («atpMixed»): Bildet den eigentlichen Dokumentationsinhalt auf Blockebene ab.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Metamodell-Definition ohne dynamische Ablauf- oder Sequenzpfade. Die Instanziierung erfolgt baumförmig, wobei ein <strong>Chapter</strong> über sein <strong>ChapterModel</strong> entweder rekursive Unterkapitel (<strong>ChapterOrMsrQuery</strong> -> <strong>Chapter</strong>), thematische Unterteilungen (<strong>TopicOrMsrQuery</strong> -> <strong>Topic1</strong>) oder direkten Kapitelinhalt (<strong>ChapterContent</strong>) einbindet. Unterhalb von <strong>Topic1</strong> und <strong>ChapterContent</strong> wird der eigentliche Text- und Tabelleninhalt über <strong>TopicContentOrMsrQuery</strong> und <strong>TopicContent</strong> bereitgestellt. Die Modellierung als «atpMixed» erlaubt textuelle Mischinhalte, während «atpVariation» Variationspunkte zur Dokumentgenerierung bzw. -konfiguration abbildet.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Spezifikationsrelevantes UML-Klassenmodell für AUTOSAR-Modellierungs- und Dokumentationswerkzeuge. Die Stereotypen «atpMixed» (Mixed-Content-XML-Serialisierung) und «atpVariation» (AUTOSAR-Variantenmechanismus) sowie die Spezialisierungen <em>Identifiable</em> und <em>Paginateable</em> bestimmen das Generierungs- und Layoutverhalten von Dokumenten. Besonderes Augenmerk liegt auf der Rekursionstiefe bei Unterkapiteln sowie der korrekten Auflösung der MSR-Queries (<code>ChapterOrMsrQuery</code>, <code>TopicOrMsrQuery</code>, <code>TopicContentOrMsrQuery</code>).</p>"}, {"id": "FIG-27b3517a45b6a3a1", "releases": ["R4.2.2", "R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodell-Struktur der eigenständigen Dokumentation (Standalone Documentation Overview) im Rahmen der AUTOSAR Generic Structure Template (AUTOSAR_TPS_GenericStructureTemplate). Das Diagramm spezifiziert die hierarchische und gemischte Strukturierung von Kapiteln, Unterthemen und Dokumentationsblöcken einschließlich Abfrage- und Variationsmechanismen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell definiert folgende Klassen, Stereotypen und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><strong>Chapter</strong> (<em>Identifiable</em>, <em>Paginateable</em>): Repräsentiert ein Dokumentkapitel. Besitzt eine gerichtete Komposition <code>+chapterModel</code> mit Kardinalität 1 zu <strong>ChapterModel</strong>.</li>\n<li><strong>ChapterModel</strong>: Aggregiert über farblich hervorgehobene (blaue) gerichtete Kompositionen drei alternative bzw. kombinierbare Kind-Elemente:</li>\n<li><code>+chapterContent</code> (0..1) zu <strong>ChapterContent</strong></li>\n<li><code>+topic1</code> (0..1) zu <strong>TopicOrMsrQuery</strong></li>\n<li><code>+chapter</code> (0..1) zu <strong>ChapterOrMsrQuery</strong></li>\n<li><strong>ChapterOrMsrQuery</strong> («atpMixed»): Bindet rekursiv über eine gerichtete Komposition <code>+chapter</code> (1) mit dem Stereotyp «atpVariation» wieder an <strong>Chapter</strong> an.</li>\n<li><strong>TopicOrMsrQuery</strong> («atpMixed»): Komponiert über <code>+topic1</code> (1) unter dem Stereotyp «atpVariation» die Klasse <strong>Topic1</strong>.</li>\n<li><strong>Topic1</strong> (<em>Identifiable</em>, <em>Paginateable</em>): Repräsentiert ein Unterthema erster Ordnung.</li>\n<li><strong>ChapterContent</strong> («atpMixed») und <strong>Topic1</strong>: Komponieren beide über gerichtete Kompositionen <code>+topicContent</code> (jeweils 0..1) die Klasse <strong>TopicContentOrMsrQuery</strong>.</li>\n<li><strong>TopicContentOrMsrQuery</strong> («atpMixed»): Komponiert über <code>+topicContent</code> (1) die Klasse <strong>TopicContent</strong>.</li>\n<li><strong>TopicContent</strong> («atpMixed»): Komponiert auf Blockebene:</li>\n<li><code>+table</code> (0..1) zu <strong>Table</strong> (<em>Paginateable</em>) mit dem Stereotyp «atpVariation»</li>\n<li><code>+blockLevelContent</code> (ohne explizite Kardinalitätsangabe) zu <strong>DocumentationBlock</strong> («atpMixed»)</li>\n<li><strong>Table</strong> (<em>Paginateable</em>): Repräsentiert Tabellenstrukturen im Dokument.</li>\n<li><strong>DocumentationBlock</strong> («atpMixed»): Bildet den eigentlichen Dokumentationsinhalt auf Blockebene ab.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Metamodell-Definition ohne dynamische Ablauf- oder Sequenzpfade. Die Instanziierung erfolgt baumförmig, wobei ein <strong>Chapter</strong> über sein <strong>ChapterModel</strong> entweder rekursive Unterkapitel (<strong>ChapterOrMsrQuery</strong> -> <strong>Chapter</strong>), thematische Unterteilungen (<strong>TopicOrMsrQuery</strong> -> <strong>Topic1</strong>) oder direkten Kapitelinhalt (<strong>ChapterContent</strong>) einbindet. Unterhalb von <strong>Topic1</strong> und <strong>ChapterContent</strong> wird der eigentliche Text- und Tabelleninhalt über <strong>TopicContentOrMsrQuery</strong> und <strong>TopicContent</strong> bereitgestellt. Die Modellierung als «atpMixed» erlaubt textuelle Mischinhalte, während «atpVariation» Variationspunkte zur Dokumentgenerierung bzw. -konfiguration abbildet.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Spezifikationsrelevantes UML-Klassenmodell für AUTOSAR-Modellierungs- und Dokumentationswerkzeuge. Die Stereotypen «atpMixed» (Mixed-Content-XML-Serialisierung) und «atpVariation» (AUTOSAR-Variantenmechanismus) sowie die Spezialisierungen <em>Identifiable</em> und <em>Paginateable</em> bestimmen das Generierungs- und Layoutverhalten von Dokumenten. Besonderes Augenmerk liegt auf der Rekursionstiefe bei Unterkapiteln sowie der korrekten Auflösung der MSR-Queries (<code>ChapterOrMsrQuery</code>, <code>TopicOrMsrQuery</code>, <code>TopicContentOrMsrQuery</code>).</p>"}, {"id": "FIG-4837251d06be7bf7", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodell-Struktur der eigenständigen Dokumentation (Standalone Documentation Overview) im Rahmen der AUTOSAR Generic Structure Template (AUTOSAR_TPS_GenericStructureTemplate). Das Diagramm spezifiziert die hierarchische und gemischte Strukturierung von Kapiteln, Unterthemen und Dokumentationsblöcken einschließlich Abfrage- und Variationsmechanismen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell definiert folgende Klassen, Stereotypen und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><strong>Chapter</strong> (<em>Identifiable</em>, <em>Paginateable</em>): Repräsentiert ein Dokumentkapitel. Besitzt eine gerichtete Komposition <code>+chapterModel</code> mit Kardinalität 1 zu <strong>ChapterModel</strong>.</li>\n<li><strong>ChapterModel</strong>: Aggregiert über farblich hervorgehobene (blaue) gerichtete Kompositionen drei alternative bzw. kombinierbare Kind-Elemente:</li>\n<li><code>+chapterContent</code> (0..1) zu <strong>ChapterContent</strong></li>\n<li><code>+topic1</code> (0..1) zu <strong>TopicOrMsrQuery</strong></li>\n<li><code>+chapter</code> (0..1) zu <strong>ChapterOrMsrQuery</strong></li>\n<li><strong>ChapterOrMsrQuery</strong> («atpMixed»): Bindet rekursiv über eine gerichtete Komposition <code>+chapter</code> (1) mit dem Stereotyp «atpVariation» wieder an <strong>Chapter</strong> an.</li>\n<li><strong>TopicOrMsrQuery</strong> («atpMixed»): Komponiert über <code>+topic1</code> (1) unter dem Stereotyp «atpVariation» die Klasse <strong>Topic1</strong>.</li>\n<li><strong>Topic1</strong> (<em>Identifiable</em>, <em>Paginateable</em>): Repräsentiert ein Unterthema erster Ordnung.</li>\n<li><strong>ChapterContent</strong> («atpMixed») und <strong>Topic1</strong>: Komponieren beide über gerichtete Kompositionen <code>+topicContent</code> (jeweils 0..1) die Klasse <strong>TopicContentOrMsrQuery</strong>.</li>\n<li><strong>TopicContentOrMsrQuery</strong> («atpMixed»): Komponiert über <code>+topicContent</code> (1) die Klasse <strong>TopicContent</strong>.</li>\n<li><strong>TopicContent</strong> («atpMixed»): Komponiert auf Blockebene:</li>\n<li><code>+table</code> (0..1) zu <strong>Table</strong> (<em>Paginateable</em>) mit dem Stereotyp «atpVariation»</li>\n<li><code>+blockLevelContent</code> (ohne explizite Kardinalitätsangabe) zu <strong>DocumentationBlock</strong> («atpMixed»)</li>\n<li><strong>Table</strong> (<em>Paginateable</em>): Repräsentiert Tabellenstrukturen im Dokument.</li>\n<li><strong>DocumentationBlock</strong> («atpMixed»): Bildet den eigentlichen Dokumentationsinhalt auf Blockebene ab.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Metamodell-Definition ohne dynamische Ablauf- oder Sequenzpfade. Die Instanziierung erfolgt baumförmig, wobei ein <strong>Chapter</strong> über sein <strong>ChapterModel</strong> entweder rekursive Unterkapitel (<strong>ChapterOrMsrQuery</strong> -> <strong>Chapter</strong>), thematische Unterteilungen (<strong>TopicOrMsrQuery</strong> -> <strong>Topic1</strong>) oder direkten Kapitelinhalt (<strong>ChapterContent</strong>) einbindet. Unterhalb von <strong>Topic1</strong> und <strong>ChapterContent</strong> wird der eigentliche Text- und Tabelleninhalt über <strong>TopicContentOrMsrQuery</strong> und <strong>TopicContent</strong> bereitgestellt. Die Modellierung als «atpMixed» erlaubt textuelle Mischinhalte, während «atpVariation» Variationspunkte zur Dokumentgenerierung bzw. -konfiguration abbildet.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Spezifikationsrelevantes UML-Klassenmodell für AUTOSAR-Modellierungs- und Dokumentationswerkzeuge. Die Stereotypen «atpMixed» (Mixed-Content-XML-Serialisierung) und «atpVariation» (AUTOSAR-Variantenmechanismus) sowie die Spezialisierungen <em>Identifiable</em> und <em>Paginateable</em> bestimmen das Generierungs- und Layoutverhalten von Dokumenten. Besonderes Augenmerk liegt auf der Rekursionstiefe bei Unterkapiteln sowie der korrekten Auflösung der MSR-Queries (<code>ChapterOrMsrQuery</code>, <code>TopicOrMsrQuery</code>, <code>TopicContentOrMsrQuery</code>).</p>"}], "trans": [{"from": "FIG-b68465f8387403ce", "to": "FIG-27b3517a45b6a3a1", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-27b3517a45b6a3a1", "to": "FIG-4837251d06be7bf7", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
